css:
/* ==== INTERFACE ====
   token  --bg #F1F4F0            页面底色｜整个视口背景与基础板面
   token  --surface #FFFFFF       内容卡片与交互操作台底色
   token  --surface-tint #E3ECE0  叶绿体基质/暗反应区域底衬
   token  --text #152217          正文与标题首选颜色
   token  --muted #4F6152         次要说明、刻度、轴线与非活动标签
   token  --border #C8D6C6        结构分割线与容器边缘
   token  --chloroplast #1E6637   主调语义色（深绿）｜类囊体膜、光反应能量载体、正向生化通量（扛起整页主要视觉）
   token  --solar #D96A00         单点锐利强调色（光量子琥珀橙）｜入射光子驱动点、当前选定操作焦点、ATP/激态爆发点
   token  --focus #D96A00         键盘焦点与交互热区轮廓
   token  --fs-h1 34px            页面主标题字号
   token  --fs-h2 22px            步骤与模态区块标题字号
   token  --fs-lead 19px          导语与关键问题提问字号
   token  --fs-body 18px          标准正文字号
   token  --fs-sec 16px           次级说明与参数注释字号
   token  --fs-label 15px         图例、轴标签与按钮文字字号
   token  --fs-tick 13px          纯数字标尺与反应式系数角标字号
   token  --font-sans             标准正文与交互字体栈
   token  --font-display          主标题与反应区核心命名展示字体栈
   token  --font-mono             化学反应计量比、波长数字与能量读数字体栈
   版心   1488×844                #stage 已含 padding: 28px 56px
   论点   以高对比度的植物生理白绿灰为基底,用深沉的类囊体叶绿素绿(--chloroplast, L=26%)建立严谨的生化反应空间骨架,仅以极小面积的高能光量子琥珀橙(--solar, L=43%, 与浅底形成极大色差且与深绿形成 60pp 的光能爆发阶差)击穿画面,彻底消除多色平摊与伪暗底疲劳
   材质   精密植物生理学实验台：硬质冷压白瓷板衬底结合高饱和植物叶绿体切片图表,线条坚实利落,无模糊光晕
   签名   能量跃迁指示针：每逢光子击中与化学键断裂，由单一点状琥珀橙(--solar)在深绿反应环路中留下极细而锐利的激发表记
   禁令   禁止同时出现多个明度接近的生化分区色（如同时平铺蓝、紫、黄、红通道）；禁止在入射光与高能电子上使用无意义的模糊外发光；禁止使用暖黄奶油色中性灰混杂
   修订   原本企图为光反应和暗反应各分配一种等面积的主色（如蓝/绿两分），导致画面平均平庸且明度差仅10多点；现改为整页统一由深沉的生化绿(--chloroplast)定调，把所有激发、操作与能量注入压缩至单一小面积、极高反差的琥珀橙(--solar)
   ==== /INTERFACE ==== */

:root {
  --pad-x: 56px;
  --pad-y: 28px;

  /* 配色系统：单一主调绿 + 极小面积锐利光能橙（明度反差与层级拉开） */
  --bg: #F1F4F0;
  --surface: #FFFFFF;
  --surface-tint: #E3ECE0;
  --border: #C8D6C6;
  --text: #152217;
  --muted: #4F6152;

  /* 核心语义：主色扛起生理框架(L=26%)，强调色只占操作焦点与光能激发(L=43%) */
  --chloroplast: #1E6637;
  --solar: #D96A00;
  --focus: #D96A00;

  /* 字阶系统 */
  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;

  /* 行高 */
  --lh-tight: 1.2;
  --lh-body: 1.45;
  --lh-relaxed: 1.6;

  /* 字体栈 */
  --font-sans: "Noto Sans CJK SC", "WenQuanYi Zen Hei", Lato, Inter, sans-serif;
  --font-display: "Noto Serif CJK SC", "AR PL SungtiL GB", "TeX Gyre Pagella", serif;
  --font-mono: "Noto Sans Mono", "Latin Modern Mono", "WenQuanYi Zen Hei Mono", monospace;

  /* 动效契约 */
  --ease-flow: cubic-bezier(0.2, 0, 0, 1);
  --duration-pulse: 240ms;
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --duration-pulse: 0ms;
  }
}
